const OVERLAP_MS = 10 * 60 * 1000;
const MAX_ORDERS = 250;

// Re-reading the last 10 minutes on every tick is safe: the sync writes Shopify's current stock, so a repeat changes nothing.
function planOrdersQuery(cursorIso, nowMs) {
  const parsed = Date.parse(cursorIso);
  const base = Number.isFinite(parsed) ? Math.min(parsed, nowMs) : nowMs;
  const since = new Date(base - OVERLAP_MS).toISOString();
  return { since, search: `updated_at:>=${since}`, first: MAX_ORDERS };
}

const ORDERS_QUERY = `query Orders($first: Int!, $search: String!) {
  orders(first: $first, query: $search, sortKey: UPDATED_AT, reverse: false) {
    nodes {
      id name email updatedAt tags
      lineItems(first: 50) { nodes { sku quantity } }
    }
  }
}`;

const STOCK_QUERY = `query Stock($search: String!) {
  productVariants(first: 250, query: $search) {
    nodes { sku inventoryQuantity inventoryItem { tracked } }
  }
}`;

const cursor = $getWorkflowStaticData('global').cursor ?? null;
const plan = planOrdersQuery(cursor, Date.now());
return [{ json: { query: ORDERS_QUERY, variables: { first: plan.first, search: plan.search } } }];

function assertNoGraphqlErrors(body, label) {
  const errors = body && Array.isArray(body.errors) ? body.errors : [];
  if (errors.length > 0) throw new Error(`${label}: ${errors.map((e) => e.message).join('; ')}`);
  if (!body || typeof body.data !== 'object' || body.data === null) throw new Error(`${label}: the response had no data`);
}

function collectSkus(orders) {
  const seen = new Set();
  for (const order of orders ?? []) {
    for (const line of order?.lineItems?.nodes ?? []) {
      const sku = typeof line?.sku === 'string' ? line.sku.trim() : '';
      if (sku) seen.add(sku);
    }
  }
  return [...seen].sort();
}

const quoteSearch = (s) => `"${String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
const quoteFormula = (s) => `'${String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;

function skusSearch(skus) {
  return skus.map((s) => `sku:${quoteSearch(s)}`).join(' OR ');
}

function airtableFormula(skus) {
  return `OR(${skus.map((s) => `{SKU}=${quoteFormula(s)}`).join(',')})`;
}

const ORDERS_QUERY = `query Orders($first: Int!, $search: String!) {
  orders(first: $first, query: $search, sortKey: UPDATED_AT, reverse: false) {
