const STOCK_QUERY = `query Stock($search: String!) {
  productVariants(first: 250, query: $search) {
    nodes { sku inventoryQuantity inventoryItem { tracked } }
  }
}`;

const body = $input.first().json;
assertNoGraphqlErrors(body, 'Shopify orders');
const skus = collectSkus(body.data.orders.nodes);
return [{ json: { hasSkus: skus.length > 0, skus, query: STOCK_QUERY, variables: { search: skusSearch(skus) }, formula: airtableFormula(skus) } }];

function assertNoGraphqlErrors(body, label) {
  const errors = body && Array.isArray(body.errors) ? body.errors : [];
  if (errors.length > 0) throw new Error(`${label}: ${errors.map((e) => e.message).join('; ')}`);
  if (!body || typeof body.data !== 'object' || body.data === null) throw new Error(`${label}: the response had no data`);
}

// Shopify's search can match neighbours (a hyphen splits words), so the answer is picked by exact SKU here.
// undefined: not found. null: no single tracked stock (untracked, ambiguous, or not a whole number).
function stockFromVariants(nodes, sku) {
  const hits = (nodes ?? []).filter((v) => v?.sku === sku);
  if (hits.length === 0) return undefined;
  if (hits.length > 1) return null;
  const variant = hits[0];
  if (variant.inventoryItem?.tracked !== true) return null;
  return Number.isInteger(variant.inventoryQuantity) ? variant.inventoryQuantity : null;
}

const isWholeStock = (n) => Number.isInteger(n) && n >= 0;

function planUpdates(skus, shopifyStock, airtableRows) {
  const bySku = new Map();
  const duplicated = new Set();
  for (const row of airtableRows ?? []) {
    if (bySku.has(row.sku)) duplicated.add(row.sku);
    else bySku.set(row.sku, row);
  }
  const result = { updates: [], skipped: [], rejected: [], unchanged: 0 };
  for (const sku of skus ?? []) {
    if (duplicated.has(sku)) {
      result.rejected.push({ sku, reason: 'duplicate SKU in Airtable' });
      continue;
    }
    const row = bySku.get(sku);
    if (!row) {
      result.skipped.push({ sku, reason: 'no Airtable row' });
      continue;
    }
    const stock = shopifyStock?.[sku];
    if (stock === undefined) {
      result.rejected.push({ sku, reason: 'SKU not found in Shopify' });
    } else if (stock === null) {
      result.rejected.push({ sku, reason: 'Shopify has no single tracked stock for this SKU' });
    } else if (!isWholeStock(stock)) {
      result.rejected.push({ sku, reason: 'Shopify stock is not a whole number of 0 or more' });
    } else if (row.stock === stock) {
      result.unchanged += 1;
    } else {
      result.updates.push({ recordId: row.id, sku, oldStock: row.stock ?? null, newStock: stock });
    }
  }
  return result;
}

function chunkUpdates(updates, size) {
  const chunks = [];
  for (let i = 0; i < (updates ?? []).length; i += size) chunks.push(updates.slice(i, i + size));
  return chunks;
}

const plan = $('Plan stock lookup').first().json;
const stockBody = $('Shopify stock').first().json;
assertNoGraphqlErrors(stockBody, 'Shopify stock');
const air = $input.first().json;
if (air.offset) throw new Error('Airtable returned more than one page of affected variants; this workflow does not paginate');
const rows = (air.records ?? []).map((r) => ({ id: r.id, sku: r.fields.SKU, stock: r.fields.Stock ?? null }));
const variants = stockBody.data.productVariants.nodes;
const stock = {};
for (const sku of plan.skus) stock[sku] = stockFromVariants(variants, sku);
const result = planUpdates(plan.skus, stock, rows);
return [{ json: { ...result, hasUpdates: result.updates.length > 0 } }];

