const { updates } = $('Plan updates').first().json;
return chunkUpdates(updates, 10).map((records) => ({ json: { records: records.map((u) => ({ id: u.recordId, fields: { Stock: u.newStock } })) } }));

function nextCursor(prevCursorIso, orders, nowMs) {
  const times = [Date.parse(prevCursorIso), ...(orders ?? []).map((o) => Date.parse(o?.updatedAt))].filter(Number.isFinite);
  const newest = times.length > 0 ? Math.max(...times) : nowMs;
  return new Date(Math.min(newest, nowMs)).toISOString();
}

const orders = $('Shopify orders').first().json.data.orders.nodes;
const store = $getWorkflowStaticData('global');
store.cursor = nextCursor(store.cursor ?? null, orders, Date.now());
return [{ json: { cursor: store.cursor, orders: orders.length } }];
